# 1. Define a dictionary to store the pitchers' information
pitchers = {}

# 2. Populate the dictionary with the pitchers' information
pitchers["Dave Rozema"] = {"G": 28, "IP": 218.1, "W": 15, "L": 7, "ERA": 3.09, "SO": 92}
pitchers["Fernando Arroyo"] = {"G": 38, "IP": 209.1, "W": 8, "L": 18, "ERA": 4.17, "SO": 60}
pitchers["Dave Roberts"] = {"G": 22, "IP": 129.1, "W": 4, "L": 10, "ERA": 5.15, "SO": 46}
pitchers["Mark Fidrych"] = {"G": 11, "IP": 81, "W": 6, "L": 4, "ERA": 2.89, "SO": 42}
pitchers["Vern Ruhle"] = {"G": 14, "IP": 66.1, "W": 3, "L": 5, "ERA": 5.70, "SO": 27}
pitchers["Jack Morris"] = {"G": 7, "IP": 45.2, "W": 1, "L": 1, "ERA": 3.74, "SO": 28}
pitchers["Ray Bare"] = {"G": 5, "IP": 14.1, "W": 0, "L": 2, "ERA": 12.56, "SO": 4}

# 3. Define a function to calculate the winning percentage of a pitcher
def calculate_winning_percentage(pitcher):
    wins = pitchers[pitcher]["W"]
    losses = pitchers[pitcher]["L"]
    return (wins / (wins + losses)) * 100

# 4. Calculate the winning percentage for each pitcher
winning_percentages = {}
for pitcher in pitchers:
    winning_percentages[pitcher] = calculate_winning_percentage(pitcher)

# 5. Sort the pitchers by their winning percentage in descending order
sorted_pitchers = sorted(winning_percentages, key=winning_percentages.get, reverse=True)

# 6. Print the top 3 best performing pitchers
print("The best performing pitchers for the 1977 Detroit Tigers are:")
for pitcher in sorted_pitchers[:3]:
    print(pitcher)
```

